BEGIN;
CREATE TABLE IF NOT EXISTS players(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE, password_hash text, coins integer NOT NULL DEFAULT 250 CHECK(coins>=0), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE players ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS sessions(token_hash char(64) PRIMARY KEY, player_id uuid NOT NULL REFERENCES players(id), expires_at timestamptz NOT NULL DEFAULT now()+interval '180 days');
CREATE TABLE IF NOT EXISTS weapons(id text PRIMARY KEY, price integer NOT NULL CHECK(price>0), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(player_id uuid REFERENCES players(id),weapon_id text REFERENCES weapons(id),bought_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(player_id,weapon_id));
CREATE TABLE IF NOT EXISTS loadouts(player_id uuid REFERENCES players(id),fighter text NOT NULL,weapon_id text,PRIMARY KEY(player_id,fighter),FOREIGN KEY(player_id,weapon_id)REFERENCES inventory(player_id,weapon_id));
CREATE TABLE IF NOT EXISTS upgrades(player_id uuid REFERENCES players(id),fighter text NOT NULL,kind text NOT NULL CHECK(kind IN('power','guard','focus')),level integer NOT NULL CHECK(level BETWEEN 1 AND 5),PRIMARY KEY(player_id,fighter,kind));
CREATE TABLE IF NOT EXISTS matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),player_id uuid NOT NULL REFERENCES players(id),fighter text NOT NULL,opponent text NOT NULL,mode text NOT NULL CHECK(mode IN('arcade','versus')),difficulty text NOT NULL CHECK(difficulty IN('easy','normal','hard')),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','finished','abandoned')),won boolean,reward integer CHECK(reward>=0),loadout jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS matches_player_started ON matches(player_id,started_at DESC);
CREATE TABLE IF NOT EXISTS ledger(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,player_id uuid NOT NULL REFERENCES players(id),delta integer NOT NULL,balance integer NOT NULL CHECK(balance>=0),reason text NOT NULL,match_id uuid UNIQUE REFERENCES matches(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT USAGE ON SCHEMA public TO fightersgame_api;
GRANT SELECT,INSERT,UPDATE ON players,inventory,loadouts,upgrades,matches TO fightersgame_api;
GRANT SELECT,INSERT,DELETE ON sessions TO fightersgame_api;
GRANT SELECT,INSERT ON ledger TO fightersgame_api;
GRANT SELECT ON weapons TO fightersgame_api;
REVOKE INSERT,UPDATE ON weapons FROM fightersgame_api;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO fightersgame_api;
COMMIT;
